ial.print(temperature, 2); //display 2 decimal places\n    Serial.println("deg C");\n\n    Serial.print("Pressure: ");\n    Serial.print(pressure, 0); //whole number only.\n    Serial.println(" Pa");\n\n    Serial.print("Ralated Atmosphere: ");\n    Serial.println(atm, 4); //display 4 decimal places\n\n    Serial.print("Altitude: ");\n    Serial.print(altitude, 2); //display 2 decimal places\n    Serial.println(" m");\n\n    Serial.println();\n\n    delay(1000); //wait a second and get values again.\n}\n'})}),"\n",(0,i.jsx)(r.p,{children:"4.Abra o monitor serial para receber os dados do sensor, incluindo temperatura, valor da press\xe3o barom\xe9trica, press\xe3o atmosf\xe9rica relativa e altitude."}),"\n",(0,i.jsx)("p",{style:{textAlign:"center"},children:(0,i.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Grove-Barometer_Sensor/img/Barometer_Sensor.jpg",alt:"pir",width:600,height:"auto"})}),"\n",(0,i.jsx)(r.p,{children:"A seguir est\xe1 um gr\xe1fico de refer\xeancia tra\xe7ando a rela\xe7\xe3o entre altitude acima do n\xedvel do mar e press\xe3o barom\xe9trica."}),"\n",(0,i.jsx)("p",{style:{textAlign:"center"},children:(0,i.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Grove-Barometer_Sensor/img/Pressure_and_Altitude.jpg",alt:"pir",width:600,height:"auto"})}),"\n",(0,i.jsx)(r.h3,{id:"com-raspberry-pi",children:"Com Raspberry Pi"}),"\n",(0,i.jsx)(r.p,{children:"1.Voc\xea deve ter um raspberry pi e um grovepi ou grovepi+."}),"\n",(0,i.jsxs)(r.p,{children:["2.Voc\xea deve ter conclu\xeddo a configura\xe7\xe3o do ambiente de desenvolvimento, caso contr\xe1rio siga as instru\xe7\xf5es ",(0,i.jsx)(r.a,{href:"/pt-br/GrovePi_Plus/",children:"aqui"}),"."]}),"\n",(0,i.jsx)(r.p,{children:"3.Conex\xe3o"}),"\n",(0,i.jsxs)(r.ul,{children:["\n",(0,i.jsx)(r.li,{children:"Conecte o sensor barom\xe9trico nos soquetes i2c do grovepi."}),"\n"]}),"\n",(0,i.jsx)(r.p,{children:"4.Navegue at\xe9 o diret\xf3rio de demos:"}),"\n",(0,i.jsx)(r.pre,{children:(0,i.jsx)(r.code,{chil